/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { HttpClient, HttpErrorResponse, provideHttpClient, withInterceptors } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { NEVER } from 'rxjs';
import { stepUpInterceptor } from './step-up.interceptor';
import { StepUpService } from './step-up.service';

describe('stepUpInterceptor', () => {
  let http: HttpClient;
  let backend: HttpTestingController;
  let stepUp: jasmine.SpyObj<StepUpService>;

  beforeEach(() => {
    stepUp = jasmine.createSpyObj<StepUpService>('StepUpService', ['start']);
    stepUp.start.and.returnValue(NEVER);
    TestBed.configureTestingModule({
      providers: [
        provideHttpClient(withInterceptors([stepUpInterceptor])),
        provideHttpClientTesting(),
        { provide: StepUpService, useValue: stepUp },
      ],
    });
    http = TestBed.inject(HttpClient);
    backend = TestBed.inject(HttpTestingController);
  });

  afterEach(() => backend.verify());

  it('starts the step-up with acr_values and max_age on 401 insufficient_user_authentication', () => {
    const errorSpy = jasmine.createSpy('error');
    http.post('/api/clients', { secret: 'x' }).subscribe({ error: errorSpy });

    backend.expectOne('/api/clients').flush(null, {
      status: 401,
      statusText: 'Unauthorized',
      headers: {
        'WWW-Authenticate':
          'Bearer error="insufficient_user_authentication", error_description="MFA required", acr_values="urn:mfa", max_age=300',
      },
    });

    expect(stepUp.start).toHaveBeenCalledOnceWith(
      jasmine.objectContaining({ method: 'POST', url: '/api/clients' }),
      jasmine.any(HttpErrorResponse),
      'urn:mfa',
      '300',
    );
    expect(errorSpy).not.toHaveBeenCalled();
  });

  it('lets a plain 401 reach the caller', () => {
    const errorSpy = jasmine.createSpy('error');
    http.get('/api/clients').subscribe({ error: errorSpy });

    backend.expectOne('/api/clients').flush(null, {
      status: 401,
      statusText: 'Unauthorized',
      headers: { 'WWW-Authenticate': 'Bearer error="invalid_token"' },
    });

    expect(stepUp.start).not.toHaveBeenCalled();
    expect(errorSpy).toHaveBeenCalledWith(jasmine.objectContaining({ status: 401 }));
  });

  it('lets other HTTP errors reach the caller', () => {
    const errorSpy = jasmine.createSpy('error');
    http.get('/api/clients').subscribe({ error: errorSpy });

    backend.expectOne('/api/clients').flush(null, { status: 500, statusText: 'Server Error' });

    expect(stepUp.start).not.toHaveBeenCalled();
    expect(errorSpy).toHaveBeenCalledWith(jasmine.objectContaining({ status: 500 }));
  });
});
